/* From Uiverse.io by Yaya12085  - Tags: button */
.__UIV_SCOPE__ .pushable {
  --dark: #5e2986;
  --medium: #8732cb;
  --light: #d08bfe;
  --white: #fff;
  cursor: pointer;
  outline: none;
  border: none;
  padding: 0;
  border-radius: 12px;
  background-color: var(--dark);
  position: relative;
}

.__UIV_SCOPE__ .front {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  padding: 12px 42px;
  border-radius: 12px;
  font-size: 1.25rem;
  font-weight: 600;
  background-color: var(--dark);
  background-image: linear-gradient(to top, var(--medium), var(--light));
  color: white;
  transform: translateY(-4px);
  border: 2px solid var(--medium);
}

.__UIV_SCOPE__ .front svg {
  width: 30px;
  height: 30px;
}
.__UIV_SCOPE__ .shadow {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 12px;
  background: hsl(0deg 0% 0% / 0.25);
  transform: translateY(2px);
}
.__UIV_SCOPE__ .pushable:focus:not(:focus-visible) {
  outline: none;
}
.__UIV_SCOPE__ .front {
  will-change: transform;
  transition: transform 250ms;
}

.__UIV_SCOPE__ .pushable:hover .front {
  transform: translateY(-6px);
}

.__UIV_SCOPE__ .pushable:active .front {
  transform: translateY(-2px);
}
